import React from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Button,
  Chip,
  Grid,
  Link,
  List,
  ListItem,
  ListItemText,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  ExpandMore as ExpandMoreIcon,
  InfoOutlined as InfoIcon,
  MenuBook as ManualIcon,
  HelpOutline as HelpIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { BRAND_BODY_LOGO_SRC } from '../constants/brand';
import {
  TROUBLESHOOTING_FAQ_ITEMS,
  TRAINING_GUIDES,
  USER_MANUAL_STEPS,
  buildHelpGuideUrl,
  getTrainingGuidesByCategory,
} from '../constants/helpCenterContent';
import { BASELINE_SOFTWARE_VERSION } from '../constants/version';

const SOFTWARE_DETAILS = [
  {
    label: 'Software Name',
    value: 'Sustainow Carbon Intelligence Solution',
  },
  {
    label: 'Purpose',
    value:
      'Enable MSMEs to operationalize carbon accounting by converting transaction, process, and document data into measurable emissions intelligence that supports continuous reduction planning and governance reporting.',
  },
  {
    label: 'Intent',
    value:
      'Deliver a practical and auditable sustainability operating layer for MSMEs that improves visibility, standardizes emissions measurement, and strengthens readiness for investor, customer, lender, and regulatory expectations.',
  },
  {
    label: 'Application Scope',
    value:
      'Applicable across manufacturing and services workflows for baseline measurement, category-level emissions diagnostics, recommendation-driven optimization, and reporting-aligned evidence management.',
  },
  {
    label: 'Primary Users',
    value:
      'MSME founders and leadership teams, plant and operations managers, sustainability and ESG officers, compliance teams, and reporting stakeholders.',
  },
  {
    label: 'Core Capabilities',
    value:
      'Carbon assessment, period-wise emissions analytics, automated data extraction, document-to-transaction processing, reduction recommendations, dashboard intelligence, compliance hub, and disclosure reporting.',
  },
  {
    label: 'Business Value',
    value:
      'Supports better cost-risk decisions, improves reporting discipline, accelerates improvement execution, and builds trust through structured sustainability evidence.',
  },
];

const InformationPage: React.FC = () => {
  const guidesByCategory = getTrainingGuidesByCategory();

  return (
    <Box sx={{ pb: 3 }}>
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ xs: 'flex-start', sm: 'center' }} sx={{ mb: 4 }}>
        <Stack spacing={0.75} alignItems="flex-start" sx={{ flexShrink: 0 }}>
          <Box
            component="img"
            src={BRAND_BODY_LOGO_SRC}
            alt="Sustainow Carbon Intelligence logo"
            sx={{ width: { xs: 200, sm: 260 }, maxWidth: '100%', height: 'auto', display: 'block' }}
          />
          <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 600 }}>
            Version {BASELINE_SOFTWARE_VERSION}
          </Typography>
        </Stack>
        <Typography variant="body1" color="text.secondary">
          Software profile and in-app usage guide. For expanded training walkthroughs and ESG FAQs, use the Help Center.
        </Typography>
      </Stack>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Paper
            elevation={0}
            sx={{
              p: { xs: 2.5, md: 3 },
              border: '1px solid rgba(76, 175, 80, 0.2)',
              background:
                'linear-gradient(135deg, rgba(76, 175, 80, 0.06) 0%, rgba(46, 125, 50, 0.08) 100%)',
            }}
          >
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={3} alignItems={{ xs: 'flex-start', md: 'center' }} justifyContent="space-between">
              <Box>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1.5 }}>
                  <InfoIcon color="primary" />
                  <Typography variant="h5" sx={{ fontWeight: 700 }}>
                    Software Profile
                  </Typography>
                </Stack>
                <Typography variant="body2" color="text.secondary">
                  Official software details, step-by-step usage guidance, and troubleshooting for users, administrators, and compliance stakeholders.
                </Typography>
              </Box>
              <Button component={RouterLink} to="/help" variant="contained" size="small">
                Open Help Center
              </Button>
            </Stack>
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3, height: '100%', border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
              Software Details
            </Typography>
            <List dense>
              {SOFTWARE_DETAILS.map((detail) => (
                <ListItem key={detail.label} alignItems="flex-start" disableGutters sx={{ mb: 1 }}>
                  <ListItemText
                    primary={
                      <Typography variant="subtitle2" color="text.secondary">
                        {detail.label}
                      </Typography>
                    }
                    secondary={<Typography variant="body1">{detail.value}</Typography>}
                  />
                </ListItem>
              ))}
            </List>
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3, height: '100%', border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
              <ManualIcon color="primary" />
              <Typography variant="h6" sx={{ fontWeight: 700 }}>
                User Manual
              </Typography>
            </Stack>
            <List dense>
              {USER_MANUAL_STEPS.map((step) => (
                <ListItem key={step.title} alignItems="flex-start" disableGutters sx={{ mb: 1 }}>
                  <ListItemText
                    primary={
                      <Link component={RouterLink} to={step.route} underline="hover" color="inherit">
                        <Typography variant="subtitle1" component="span">
                          {step.title}
                        </Typography>
                      </Link>
                    }
                    secondary={<Typography variant="body2" color="text.secondary">{step.description}</Typography>}
                  />
                </ListItem>
              ))}
            </List>
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 3, border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
              <ManualIcon color="primary" />
              <Typography variant="h6" sx={{ fontWeight: 700 }}>
                Training guide index
              </Typography>
            </Stack>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Each module has a detailed walkthrough in the Help Center. Open a guide below or jump to a workspace directly.
            </Typography>
            {guidesByCategory.map(({ category, label, guides }) => (
              <Box key={category} sx={{ mb: 2 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
                  {label}
                </Typography>
                <Stack direction="row" flexWrap="wrap" useFlexGap spacing={1}>
                  {guides.map((guide) => (
                    <Chip
                      key={guide.id}
                      component={RouterLink}
                      to={buildHelpGuideUrl(guide.id)}
                      clickable
                      label={guide.title}
                      variant="outlined"
                      size="small"
                    />
                  ))}
                </Stack>
              </Box>
            ))}
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
              {TRAINING_GUIDES.length} guides covering onboarding through enterprise reporting.
            </Typography>
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 3, border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Stack
              direction={{ xs: 'column', sm: 'row' }}
              spacing={1}
              alignItems={{ xs: 'flex-start', sm: 'center' }}
              justifyContent="space-between"
              sx={{ mb: 2 }}
            >
              <Stack direction="row" spacing={1} alignItems="center">
                <HelpIcon color="primary" />
                <Typography variant="h6" sx={{ fontWeight: 700 }}>
                  Troubleshooting
                </Typography>
              </Stack>
              <Button component={RouterLink} to="/help" variant="outlined" size="small">
                Open Help Center
              </Button>
            </Stack>
            {TROUBLESHOOTING_FAQ_ITEMS.map((item) => (
              <Accordion key={item.id} disableGutters>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography sx={{ fontWeight: 600 }}>{item.question}</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Typography color="text.secondary">{item.answer}</Typography>
                </AccordionDetails>
              </Accordion>
            ))}
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default InformationPage;
